export default {
    async fetch(request, env) {

        const headers = {
              "Access-Control-Allow-Origin": "*",
                    "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
                          "Access-Control-Allow-Headers": "Content-Type",
                                "Content-Type": "application/json;charset=UTF-8"
                                    };

                                        // CORS 预检
                                            if (request.method === "OPTIONS") {
                                                  return new Response(null, {
                                                          status: 204,
                                                                  headers
                                                                        });
                                                                            }

                                                                                const url = new URL(request.url);

                                                                                    // =========================
                                                                                        // POST /letter
                                                                                            // 创建一封信
                                                                                                // =========================
                                                                                                    if (
                                                                                                          request.method === "POST" &&
                                                                                                                url.pathname === "/letter"
                                                                                                                    ) {
                                                                                                                          try {
                                                                                                                                  const data = await request.json();

                                                                                                                                          if (
                                                                                                                                                    !data.text ||
                                                                                                                                                              typeof data.text !== "string"
                                                                                                                                                                      ) {
                                                                                                                                                                                return out(
                                                                                                                                                                                            { error: "内容不能为空" },
                                                                                                                                                                                                        400,
                                                                                                                                                                                                                    headers
                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                              if (data.text.length > 10000) {
                                                                                                                                                                                                                                                        return out(
                                                                                                                                                                                                                                                                    { error: "内容过长" },
                                                                                                                                                                                                                                                                                400,
                                                                                                                                                                                                                                                                                            headers
                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                      // 生成唯一 ID
                                                                                                                                                                                                                                                                                                                              const id = crypto
                                                                                                                                                                                                                                                                                                                                        .randomUUID()
                                                                                                                                                                                                                                                                                                                                                  .replace(/-/g, "");

                                                                                                                                                                                                                                                                                                                                                          // 保存进 KV
                                                                                                                                                                                                                                                                                                                                                                  await env.LETTERS.put(
                                                                                                                                                                                                                                                                                                                                                                            id,
                                                                                                                                                                                                                                                                                                                                                                                      JSON.stringify({
                                                                                                                                                                                                                                                                                                                                                                                                  text: data.text,
                                                                                                                                                                                                                                                                                                                                                                                                              createdAt: Date.now()
                                                                                                                                                                                                                                                                                                                                                                                                                        })
                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                        return out(
                                                                                                                                                                                                                                                                                                                                                                                                                                                  {
                                                                                                                                                                                                                                                                                                                                                                                                                                                              success: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          id: id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              200,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        headers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return out(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    error: "请求格式错误"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        400,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  headers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // =========================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // GET /letter/:id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 读取一封信
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // =========================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              request.method === "GET" &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    url.pathname.startsWith("/letter/")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const id = url.pathname
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      .split("/")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              .pop();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const data = await env.LETTERS.get(id);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!data) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return out(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        error: "信件不存在"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            404,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      headers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return out(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  JSON.parse(data),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          200,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  headers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // =========================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 健康检查
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // =========================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return out(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          status: "ok"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      200,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            headers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  };


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // JSON 返回函数
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function out(data, status, headers) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return new Response(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        JSON.stringify(data),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  status: status,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        headers: headers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
}